def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into a single dictionary.

    Args:
    dict1: The first dictionary.
    dict2: The second dictionary.
    dict3: The third dictionary.

    Returns:
    A single dictionary containing all key-value pairs from the input dictionaries,
    with later dictionaries overwriting values for duplicate keys.
    """
    # Merge dictionaries in the order they are passed, 
    # with later dictionaries overwriting earlier ones in case of key conflicts.
    merged_dict = {}
    for d in [dict1, dict2, dict3]:
        merged_dict.update(d)
    return merged_dict

# Example usage and test cases:
assert merge_dictionaries_three(
    {"R": "Red", "B": "Black", "P": "Pink"},
    {"G": "Green", "W": "White"},
    {"O": "Orange", "W": "White", "B": "Black"}
) == {'B': 'Black', 'R': 'Red', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'O': 'Orange'}

assert merge_dictionaries_three(
    {"R": "Red", "B": "Black", "P": "Pink"},
    {"G": "Green", "W": "White"},
    {"L": "lavender", "B": "Blue"}
) == {'R': 'Red', 'B': 'Blue', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'L': 'lavender'}

